   938|    for (let processed = 0; processed < MAX_QUEUE_RETAINED; processed += 1) {
   939|      const result = await processNextSeniorDeveloperJob();
   940|      if (!result) break;
   941|    }
   942|  } finally {
   943|    draining = false;
